/*
 1. COMPOSITION: three 1.5x1.9 cards in a row (gap 0.25, row 5.0w) centered at origin; center card focal, sits slightly proud; gradient backdrop plane 7x6 at z=-2.5; contact shadow discs under each card.
 2. LIGHT RIG: rig-studio-neutral — key #fff6ec 2.6 upper-left-ish [2.4,2.8,2.2], fill #e8ecf2 0.7, rim #ffffff 1.6 behind; ambient floor 0.18. Node-local, all bounded.
 3. MATERIALS: card slabs MeshStandardNodeMaterial with TSL vertical ramp #191921->#121218, roughness 0.6, metalness 0.25; hairline border #26262f via TSL edge mask; machined icon discs metalness 0.5, roughness 0.55; glyphs/text MSDF paper #e8ecf2, accent #ff2a38 emissive glyphs.
 4. MOTION: stagger-cards mount — fade-up y +0.2->0, 0.5s power2.out, 80ms stagger; hover lift y+0.06/z+0.12 over 180ms, shadow widens+softens, glyph emissive 1.6->2.2; press 0.97 in 120ms.
 5. FOCAL: center card's red-emissive icon disc glyph ("02") — the single brightest element.
*/
import {
  Group, Mesh, PlaneGeometry, CylinderGeometry, CircleGeometry,
  DirectionalLight, AmbientLight, Color,
  MeshBasicNodeMaterial, MeshStandardNodeMaterial,
} from 'three/webgpu';
import { uv, vec3, vec2, mix, smoothstep, float, color, abs, max, uniform, sub } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new Group();
  root.name = 'feature-triptych';

  const colors = config.intent?.visualSpec?.colors ?? {};
  const C = {
    background: colors.background ?? '#0b0b10',
    surface: colors.surface ?? '#16161d',
    ink: colors.ink ?? '#16161d',
    paper: colors.paper ?? '#e8ecf2',
    accent: colors.accent ?? '#ff2a38',
    stops: colors.gradientStops ?? [{ at: 0, hex: '#191921' }, { at: 1, hex: '#121218' }],
  };

  const disposables = [];
  const timelines = [];
  const primHandles = [];

  // ---------- backdrop stage (color.background / color.gradient stage wash) ----------
  function buildBackdrop() {
    const geo = new PlaneGeometry(7, 6);
    const mat = new MeshBasicNodeMaterial();
    const top = new Color(C.stops[0].hex).lerp(new Color(C.background), 0.35);
    const bottom = new Color(C.background);
    const v = uv().y;
    // subtle vignette so the stage never reads as flat void
    const d = uv().sub(vec2(0.5, 0.5)).length();
    const grad = mix(vec3(bottom.r, bottom.g, bottom.b), vec3(top.r, top.g, top.b), smoothstep(0.0, 1.0, v));
    mat.colorNode = mix(grad, grad.mul(0.55), smoothstep(0.35, 0.85, d));
    const mesh = new Mesh(geo, mat);
    mesh.position.set(0, 0, -2.5);
    disposables.push(geo, mat);
    return mesh;
  }
  root.add(buildBackdrop());

  // ---------- light rig (rig-studio-neutral, node-local) ----------
  function buildLightRig() {
    const rig = new Group();
    const key = new DirectionalLight('#fff6ec', 2.6);
    key.position.set(2.4, 2.8, 2.2);
    key.target.position.set(0, 0.4, 0);
    const fill = new DirectionalLight('#e8ecf2', 0.7);
    fill.position.set(-2.6, 1.2, 1.8);
    fill.target.position.set(0, 0.4, 0);
    const rim = new DirectionalLight('#ffffff', 1.5);
    rim.position.set(-1.2, 2.2, -2.6);
    rim.target.position.set(0, 0.6, 0);
    const amb = new AmbientLight('#e8ecf2', 0.18);
    rig.add(key, key.target, fill, fill.target, rim, rim.target, amb);
    return rig;
  }
  root.add(buildLightRig());

  // ---------- card face material: gradient ramp + hairline border ----------
  const CARD_W = 1.5, CARD_H = 1.9, GAP = 0.25;
  function makeCardMaterial() {
    const mat = new MeshStandardNodeMaterial();
    const s0 = new Color(C.stops[0].hex);
    const s1 = new Color(C.stops[C.stops.length - 1].hex);
    const ramp = mix(
      vec3(s0.r, s0.g, s0.b),
      vec3(s1.r, s1.g, s1.b),
      smoothstep(0.0, 1.0, sub(1.0, uv().y))
    );
    // hairline border 0.006 units -> normalized per axis
    const bx = float(0.006 / CARD_W);
    const by = float(0.006 / CARD_H);
    const ex = smoothstep(bx, bx.mul(1.6), uv().x.min(sub(1.0, uv().x)));
    const ey = smoothstep(by, by.mul(1.6), uv().y.min(sub(1.0, uv().y)));
    const inner = ex.mul(ey);
    const border = new Color('#26262f');
    mat.colorNode = mix(vec3(border.r, border.g, border.b), ramp, inner);
    mat.roughnessNode = float(0.6);
    mat.metalnessNode = float(0.25);
    disposables.push(mat);
    return mat;
  }

  // ---------- card content ----------
  const cardsData = [
    { glyph: '01', title: 'In-House Calibre', body: 'Every movement is designed, machined, and finished under one roof.' },
    { glyph: '02', title: 'Five-Year Guarantee', body: 'Each piece is serviced free of charge for five years from delivery.' },
    { glyph: '03', title: 'Hand-Finished Dials', body: 'Guilloche cut on a 1912 rose engine, one dial at a time.' },
  ];
  // bridge to spec textContent if present
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  if (items.length >= 9) {
    for (let i = 0; i < 3; i++) {
      cardsData[i].glyph = items[i * 3].text;
      cardsData[i].title = items[i * 3 + 1].text;
      cardsData[i].body = items[i * 3 + 2].text;
    }
  }

  const cards = [];
  const shadowMats = [];
  const glyphEmissiveUniforms = [];

  function buildIconDisc(glyph, focal) {
    const disc = new Group();
    const geo = new CylinderGeometry(0.2, 0.2, 0.05, 48);
    const mat = new MeshStandardNodeMaterial();
    const surf = new Color(C.surface).lerp(new Color(C.paper), 0.12);
    mat.colorNode = vec3(surf.r, surf.g, surf.b);
    mat.roughnessNode = float(0.55);
    mat.metalnessNode = float(0.5);
    const body = new Mesh(geo, mat);
    body.rotation.x = Math.PI / 2;
    disc.add(body);
    disposables.push(geo, mat);

    // glyph carried on disc, accent red, emissive-driven via material on MSDF text
    const glyphObj = ctx.fontAtlas.createText(String(glyph), {
      fontSize: 20, color: C.accent, align: 'center',
    });
    glyphObj.position.set(0, -0.005, 0.032);
    glyphObj.scale.setScalar(0.011);
    disc.add(glyphObj);

    // emissive halo plane behind disc — single brightest read, focal on center card
    const haloGeo = new CircleGeometry(0.24, 48);
    const haloMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
    const acc = new Color(C.accent);
    const em = uniform(focal ? 1.6 : 1.1);
    const dd = uv().sub(vec2(0.5, 0.5)).length().mul(2.0);
    haloMat.colorNode = vec3(acc.r, acc.g, acc.b).mul(em.mul(0.28));
    haloMat.opacityNode = smoothstep(1.0, 0.1, dd).mul(0.55);
    const halo = new Mesh(haloGeo, haloMat);
    halo.position.z = -0.02;
    disc.add(halo);
    disposables.push(haloGeo, haloMat);
    glyphEmissiveUniforms.push(em);

    return { disc, em };
  }

  function buildCard(data, i) {
    const holder = new Group(); // static slot position
    const card = new Group();   // animated lift target
    holder.add(card);

    const x = (i - 1) * (CARD_W + GAP);
    const focal = i === 1;
    holder.position.set(x, focal ? 0.06 : 0, focal ? 0.08 : 0);

    // slab
    const faceGeo = new PlaneGeometry(CARD_W, CARD_H);
    const face = new Mesh(faceGeo, makeCardMaterial());
    card.add(face);
    disposables.push(faceGeo);

    // slight extrusion back panel for physical depth
    const backGeo = new PlaneGeometry(CARD_W, CARD_H);
    const backMat = new MeshStandardNodeMaterial();
    const inkC = new Color(C.ink);
    backMat.colorNode = vec3(inkC.r, inkC.g, inkC.b);
    backMat.roughnessNode = float(0.7);
    backMat.metalnessNode = float(0.2);
    const back = new Mesh(backGeo, backMat);
    back.position.z = -0.04;
    card.add(back);
    disposables.push(backGeo, backMat);

    // interior layout: padding 0.375, icon seat -> 0.25 gap -> title -> 0.125 gap -> body
    const topY = CARD_H / 2 - 0.375;
    const { disc, em } = buildIconDisc(data.glyph, focal);
    disc.position.set(0, topY - 0.2, 0.05);
    card.add(disc);

    const title = ctx.fontAtlas.createText(String(data.title), {
      fontSize: 20, color: C.paper, align: 'center', maxWidthPx: 220,
    });
    title.position.set(0, topY - 0.4 - 0.25 - 0.1, 0.02);
    title.scale.setScalar(0.011);
    card.add(title);

    const bodyText = ctx.fontAtlas.createText(String(data.body), {
      fontSize: 13, color: C.paper, align: 'center', maxWidthPx: 200,
    });
    bodyText.position.set(0, topY - 0.4 - 0.25 - 0.2 - 0.125 - 0.18, 0.02);
    bodyText.scale.setScalar(0.011);
    card.add(bodyText);

    // contact shadow (grounding)
    const shGeo = new CircleGeometry(1.0, 48);
    const shMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
    const shD = uv().sub(vec2(0.5, 0.5)).length().mul(2.0);
    const shOp = uniform(0.5);
    shMat.colorNode = vec3(0, 0, 0);
    shMat.opacityNode = smoothstep(1.0, 0.0, shD).mul(shOp);
    const shadow = new Mesh(shGeo, shMat);
    shadow.rotation.x = -Math.PI / 2;
    shadow.position.set(0, -CARD_H / 2 - 0.08, 0.1);
    shadow.scale.set(CARD_W * 0.85, CARD_H * 0.28, 1);
    holder.add(shadow);
    disposables.push(shGeo, shMat);
    shadowMats.push(shOp);

    cards.push({ holder, card, shadow, shOp, em, focal });
    return holder;
  }

  cardsData.forEach((d, i) => root.add(buildCard(d, i)));

  // ---------- mount: stagger-cards fade-up ----------
  const mountTl = gsap.timeline();
  cards.forEach((c, i) => {
    const targets = [];
    c.card.traverse((o) => { if (o.material) targets.push(o.material); });
    targets.forEach((m) => { if ('opacity' in m) { /* keep MSDF/opacity as-is */ } });
    mountTl.fromTo(
      c.card.position,
      { y: -0.2 },
      { y: 0, duration: 0.5, ease: 'power2.out' },
      i * 0.08
    );
    mountTl.fromTo(
      c.card.scale,
      { x: 0.98, y: 0.98, z: 0.98 },
      { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
      i * 0.08
    );
  });
  timelines.push(mountTl);

  // ---------- primitives from config (none expected, but honor contract) ----------
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    const fn = ctx.primitives?.[p.name];
    if (fn) primHandles.push(fn(root, p.params));
  }

  // ---------- interactions: hover lift / press ----------
  const hoverTls = new Map();
  function liftCard(idx, on) {
    const c = cards[idx];
    if (!c) return;
    const prev = hoverTls.get(idx);
    if (prev) prev.kill();
    const tl = gsap.timeline();
    if (on) {
      tl.to(c.card.position, { y: 0.06, z: 0.12, duration: 0.18, ease: 'power2.out' }, 0);
      tl.to(c.shadow.scale, { x: CARD_W * 1.05, y: CARD_H * 0.34, duration: 0.18, ease: 'power2.out' }, 0);
      tl.to(c.shOp, { value: 0.32, duration: 0.18, ease: 'power2.out' }, 0);
      tl.to(c.em, { value: 2.2, duration: 0.18, ease: 'power2.out' }, 0);
    } else {
      tl.to(c.card.position, { y: 0, z: 0, duration: 0.18, ease: 'power2.out' }, 0);
      tl.to(c.shadow.scale, { x: CARD_W * 0.85, y: CARD_H * 0.28, duration: 0.18, ease: 'power2.out' }, 0);
      tl.to(c.shOp, { value: 0.5, duration: 0.18, ease: 'power2.out' }, 0);
      tl.to(c.em, { value: c.focal ? 1.6 : 1.1, duration: 0.18, ease: 'power2.out' }, 0);
    }
    hoverTls.set(idx, tl);
    timelines.push(tl);
  }

  function cardIndexFromHit(hit) {
    let o = hit?.object ?? hit;
    while (o) {
      const idx = cards.findIndex((c) => c.holder === o || c.card === o);
      if (idx >= 0) return idx;
      o = o.parent;
    }
    return -1;
  }

  root.userData.handlers = {
    pointerover: (e) => { const i = cardIndexFromHit(e); if (i >= 0) liftCard(i, true); },
    pointerout: (e) => { const i = cardIndexFromHit(e); if (i >= 0) liftCard(i, false); },
    pointerdown: (e) => {
      const i = cardIndexFromHit(e);
      if (i >= 0) {
        const tl = gsap.timeline();
        tl.to(cards[i].card.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' })
          .to(cards[i].card.scale, { x: 1, y: 1, z: 1, duration: 0.25, ease: 'power2.out' });
        timelines.push(tl);
      }
    },
  };

  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    hoverTls.forEach((t) => t.kill());
    primHandles.forEach((h) => h?.cleanup?.());
    disposables.forEach((d) => d?.dispose?.());
    root.traverse((o) => {
      if (o.geometry?.dispose) o.geometry.dispose();
      const m = o.material;
      if (m) (Array.isArray(m) ? m : [m]).forEach((mm) => mm?.dispose?.());
    });
  };

  return root;
}

/* @spec-manifest
{"elements":[
{"id":"text.icon-glyph.0","where":"buildIconDisc","how":"MSDF glyph 01 on machined disc"},
{"id":"text.card-title.1","where":"buildCard","how":"fontAtlas title, card 0"},
{"id":"text.body.2","where":"buildCard","how":"fontAtlas body, card 0"},
{"id":"text.icon-glyph.3","where":"buildIconDisc","how":"MSDF glyph 02, focal card"},
{"id":"text.card-title.4","where":"buildCard","how":"fontAtlas title, card 1"},
{"id":"text.body.5","where":"buildCard","how":"fontAtlas body, card 1"},
{"id":"text.icon-glyph.6","where":"buildIconDisc","how":"MSDF glyph 03 on disc"},
{"id":"text.card-title.7","where":"buildCard","how":"fontAtlas title, card 2"},
{"id":"text.body.8","where":"buildCard","how":"fontAtlas body, card 2"},
{"id":"color.background","where":"buildBackdrop","how":"stage gradient base color"},
{"id":"color.surface","where":"buildIconDisc","how":"disc base albedo"},
{"id":"color.ink","where":"buildCard","how":"card back panel albedo"},
{"id":"color.paper","where":"buildCard","how":"title and body text color"},
{"id":"color.accent","where":"buildIconDisc","how":"glyph color and emissive halo"},
{"id":"color.gradient","where":"makeCardMaterial","how":"vertical ramp 191921 to 121218"},
{"id":"effects.spec","where":"buildCard","how":"1.5x1.9 cards, gap 0.25, lift states"}
]}
*/
